/* BUILD is generated by Vite from the application shell and its contents. */
const SHELL_PREFIX = 'simpleshop-shell-';
const SHELL = SHELL_PREFIX + BUILD.version;
const API_CACHE = 'simpleshop-public-products-v1';
const IMAGE_CACHE = 'simpleshop-static-images-v1';
const API_MAX_ENTRIES = 64;
const IMAGE_MAX_ENTRIES = 120;
const API_MAX_AGE = 30 * 24 * 60 * 60 * 1000;
const shellPaths = new Set(BUILD.urls);
const appRoutes = new Set(['/', '/about', '/products', '/dashboard', '/login', '/signup', '/profile', '/offline']);
let pendingWrites = Promise.resolve();

self.addEventListener('install', (event) => {
  event.waitUntil(caches.open(SHELL).then((cache) => cache.addAll(
    BUILD.urls.map((url) => new Request(url, { cache: 'reload' })),
  )));
});

self.addEventListener('activate', (event) => {
  event.waitUntil((async () => {
    const names = await caches.keys();
    await Promise.all(names.filter((name) => name.startsWith(SHELL_PREFIX) && name !== SHELL)
      .map((name) => caches.delete(name)));
    await self.clients.claim();
  })());
});

self.addEventListener('message', (event) => {
  if (event.data?.type === 'ACTIVATE_UPDATE') event.waitUntil(self.skipWaiting());
});

function putBounded(cache, key, response, maximum) {
  const write = pendingWrites.then(async () => {
    await cache.delete(key);
    await cache.put(key, response);
    const keys = await cache.keys();
    await Promise.all(keys.slice(0, Math.max(0, keys.length - maximum)).map((item) => cache.delete(item)));
  });
  pendingWrites = write.catch(() => {});
  return pendingWrites;
}

function publicProductUrl(request, url) {
  if (url.origin !== 'https://dummyjson.com' || request.credentials !== 'omit'
      || request.headers.has('authorization')) return false;
  return (url.pathname === '/products' && url.search === '?limit=0')
    || (/^\/products\/[1-9]\d*$/.test(url.pathname) && !url.search);
}

function withHeaders(response, values) {
  const headers = new Headers(response.headers);
  for (const [key, value] of Object.entries(values)) headers.set(key, value);
  return new Response(response.body, { status: response.status, statusText: response.statusText, headers });
}

async function cachedProduct(cache, request) {
  const response = await cache.match(request);
  if (!response) return undefined;

  const storedAt = Number(response.headers.get('X-SimpleShop-Stored-At'));
  if (!storedAt || Date.now() - storedAt > API_MAX_AGE) {
    await cache.delete(request);
    return undefined;
  }

  return response;
}

async function networkFirst(request) {
  const cache = await caches.open(API_CACHE);

  try {
    const response = await fetch(request, { cache: 'no-store', signal: AbortSignal.timeout(4500) });
    if (!response.ok) {
      if (response.status >= 500 || response.status === 429) throw new Error('API temporarily unavailable');
      if (response.status === 404) await cache.delete(request);
      return response;
    }
    if (!response.headers.get('Content-Type')?.includes('application/json')) {
      throw new Error('Invalid API response');
    }
    await putBounded(cache, request, withHeaders(response.clone(), {
      'X-SimpleShop-Stored-At': String(Date.now()),
    }), API_MAX_ENTRIES);
    return response;
  } catch {
    const cached = await cachedProduct(cache, request);
    if (cached) return withHeaders(cached, { 'X-SimpleShop-Source': 'offline-cache' });
    return new Response(JSON.stringify({ message: 'This data is unavailable. Reconnect and try again.' }), {
      status: 503,
      headers: { 'Content-Type': 'application/json' },
    });
  }
}

async function cacheFirstImage(request) {
  const cache = await caches.open(IMAGE_CACHE);
  const cached = await cache.match(request);
  if (cached) return cached;

  try {
    const response = await fetch(request);
    if (response.ok || response.type === 'opaque') {
      await putBounded(cache, request, response.clone(), IMAGE_MAX_ENTRIES);
      return response;
    }
  } catch {
    // Unavailable images use the same local placeholder as failed HTTP responses.
  }
  const shell = await caches.open(SHELL);
  return shell.match('/offline-image.svg');
}

async function navigate(request, url) {
  const path = url.pathname.replace(/\/$/, '') || '/';
  const shell = await caches.open(SHELL);
  const index = await shell.match('/index.html');

  if (appRoutes.has(path)) return index;
  const details = path.match(/^\/products\/([1-9]\d*)$/);
  if (details) {
    const cache = await caches.open(API_CACHE);
    if (await cachedProduct(cache, 'https://dummyjson.com/products/' + details[1])) return index;
  }

  try {
    const response = await fetch(request, { cache: 'no-store', signal: AbortSignal.timeout(4500) });
    return response.ok ? index : response;
  } catch {
    return shell.match('/offline.html');
  }
}

self.addEventListener('fetch', (event) => {
  const { request } = event;
  if (request.method !== 'GET') return;
  const url = new URL(request.url);
  if (publicProductUrl(request, url)) {
    event.respondWith(networkFirst(request));
  } else if (url.origin === self.location.origin && request.mode === 'navigate') {
    event.respondWith(navigate(request, url));
  } else if (url.origin === self.location.origin && shellPaths.has(url.pathname)) {
    event.respondWith(caches.open(SHELL).then(async (cache) => (await cache.match(url.pathname)) || fetch(request)));
  } else if (url.origin === 'https://cdn.dummyjson.com' && request.destination === 'image'
      && url.pathname.startsWith('/product-images/')) {
    event.respondWith(cacheFirstImage(request));
  }
});
